const float PI = 3.14159265359;

vec4 circle(vec2 pos, vec2 center, float radius, vec3 color, float antialias, float thickness)
{
    float d = length(pos - center) - radius;
    float t = smoothstep(thickness, antialias + thickness, abs(d));
    return vec4(color, 1.0 - t);
}

float getMetaBallValue(vec2 center, float radius, vec2 current)
{
    float meta = radius / distance(current, center);
    meta *= meta;
    return meta;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    const int MetaBallAmount = 15;

    // x, y is coordiante, z is radius
    vec3 metaBalls[MetaBallAmount];
    for(int i = 0; i < MetaBallAmount; ++i)
    {
        float index = float(i + 1);
        vec3 random = hash31(index);

        float startTheta = mix(0., PI * 2., random.x);
        float deltaTheta = iTime * mix(0.1 * PI, 0.4 * PI, random.y);
        float theta = startTheta + deltaTheta;
        random = hash33(random);
        vec2 coordinate = vec2(cos(theta), sin(theta + deltaTheta * floor(random.x * 2.))) * mix(5., 10., random.y);

        float radius = mix(0.5, 2., random.z);
        metaBalls[i] = vec3(coordinate, radius);
    }

    const float VerticalWorldSize = 30.;
    float worldToPixel = iResolution.y / VerticalWorldSize;
    float pixelToWorld = 1. / worldToPixel;

    if( iMouse.z > 0.0 )
    {
        vec3 mouseMetaBall = metaBalls[0];
        mouseMetaBall.xy =(iMouse.xy - iResolution.xy * 0.5) * pixelToWorld;
        metaBalls[0] = mouseMetaBall;
    }
    // screen center is at world (0, 0)
    vec2 coordinate = (fragCoord - iResolution.xy * 0.5) * pixelToWorld;

    float meta = 0.;
    for(int i = 0; i < MetaBallAmount; ++i)
    {
        vec3 ball = metaBalls[i]; // coordinate (x,y), radius(z)
        meta += getMetaBallValue(ball.xy, ball.z, coordinate);
    }
    vec3 col = vec3(smoothstep(-1., 1., (meta - 1.3) / min(1., fwidth(meta))));
    if( iMouse.z > 0.0 )
    {
        // debug circle
        for(int i = 0; i < MetaBallAmount; ++i)
        {
            vec3 ball = metaBalls[i];
            vec4 circleCol = circle(coordinate, ball.xy, ball.z, vec3(0, 1, 0), 1. * pixelToWorld, 0.5 * pixelToWorld);
            col = mix(col, circleCol.rgb, circleCol.a);
        }
    }

    // Output to screen
    fragColor = vec4(col, 1.0);
}

